<?php
/* Phase 301: attach model-specific transparent generated product images. */
add_action('init',function(){
if(get_option('bhc_catalog_image_emersun_batch_v301'))return;
$map=['CB16CLA'=>'emersun-cb16cla-source.png','TF11T220'=>'emersun-tf11t220-source.png','TFH17/EL'=>'emersun-tfh17el-source.png','CB17EL'=>'emersun-cb17el-source.png','NRF329D'=>'emersun-nrf329d-source.png'];$result=[];
foreach($map as $model=>$srcname){$id=0;$pids=get_posts(['post_type'=>'product','post_status'=>'any','posts_per_page'=>1,'fields'=>'ids','meta_key'=>'_bhc_model','meta_value'=>$model]);if($pids)$id=(int)$pids[0];$src=__DIR__.'/'.$srcname;$rel='bhc-image-references/emersun-'.sanitize_title($model).'-generated-4k.png';$file=ABSPATH.'wp-content/uploads/'.$rel;$ok=false;$aid=0;if($id&&is_readable($src)){$im=@imagecreatefrompng($src);if($im){wp_mkdir_p(dirname($file));$w=imagesx($im);$h=imagesy($im);$scale=4096/max($w,$h);$nw=max(1,(int)round($w*$scale));$nh=max(1,(int)round($h*$scale));$c=imagecreatetruecolor($nw,$nh);imagealphablending($c,false);imagesavealpha($c,true);$z=imagecolorallocatealpha($c,0,0,0,127);imagefill($c,0,0,$z);imagecopyresampled($c,$im,0,0,0,0,$nw,$nh,$w,$h);imagepng($c,$file,6);imagedestroy($c);imagedestroy($im);$ok=is_readable($file);}}if($ok){$old=get_post_thumbnail_id($id);if($old)wp_delete_attachment($old,false);$aid=wp_insert_attachment(['post_mime_type'=>'image/png','post_title'=>'Emersun '.$model.' اختصاصی 4K شفاف','post_status'=>'inherit','post_parent'=>$id],$file,$id);if($aid&&!is_wp_error($aid)){update_post_meta($aid,'_wp_attached_file',$rel);$q=@getimagesize($file);wp_update_attachment_metadata($aid,['width'=>$q[0]??4096,'height'=>$q[1]??4096,'file'=>$rel,'sizes'=>[]]);set_post_thumbnail($id,$aid);update_post_meta($id,'_bhc_image_generation_status','product_specific_generated_candidate');update_post_meta($id,'_bhc_image_status','generated_4k_transparent_candidate');update_post_meta($id,'_bhc_image_long_edge',max((int)($q[0]??0),(int)($q[1]??0)));update_post_meta($id,'_bhc_image_featured_verified','yes');}}$result[$model]=['id'=>$id,'ok'=>$ok,'attachment'=>$aid];}
update_option('bhc_catalog_image_emersun_batch_v301',['result'=>$result,'at'=>current_time('mysql')],false);
},301);
